@@ -109,6 +109,14 @@
 	status = "okay";
 	sda-pin = <30>;
 	scl-pin = <7>;
+
+	mma8653fc@1d {
+		compatible = "nxp,fxos8700","nxp,mma8653fc";
+		reg = <0x1d>;
+		label = "MMA8653FC";
+		int1-gpios = <&gpio0 28 0>;
+		int2-gpios = <&gpio0 27 0>;
+	};
 };
 
 &i2c1 {
diff --git a/boards/arm/nrf51_pca10028/nrf51_pca10028_defconfig b/boards/arm/nrf51_pca10028/nrf51_pca10028_defconfig
index 94177e85d0..a4c5f8f413 100644
